if __name__ == "__main__":
    # Run on port 8081 to avoid conflict with default services (like Open WebUI's own internal API)
    uvicorn.run(app, host="127.0.0.1", port=8081)

@app.post("/v1/chat/completions")
async def chat_completions(request: ChatCompletionRequest):
    try:
        # Extract the last user message
        user_query = ""
        for msg in reversed(request.messages):
            if msg.role == "user":
                user_query = msg.content
                break

        # 1. Clean and Prefix Query
        cleaned_q = clean_turkish_text(user_query)
        formatted_q = prepare_e5_input(cleaned_q, is_query=True)

        # 2. Retrieve Relevant Context (Main DB only for API)
        # Limit context to prevent OOM / Context overflow
        print(f"[*] Querying database for: {cleaned_q[:50]}...")
        docs = MAIN_VS.similarity_search(formatted_q, k=3)
        context = "\n\n".join([d.page_content.replace("passage: ", "") for d in docs])

        # 3. Format Prompt
        from src.prompts import RAG_PROMPT
        final_prompt = RAG_PROMPT.format(
            chat_history="", # Open WebUI handles its own history
            context=context, 
            question=cleaned_q
        )

        # 4. Safety: Truncate if extremely long (Safety valve for 3B model)
        # 1 token is roughly 4 chars. 4096 tokens ~ 16000 chars.
        if len(final_prompt) > 15000:
            print(f"Warning: Prompt too long ({len(final_prompt)} chars). Truncating user query.")
            cleaned_q = cleaned_q[:5000] + "... [TRUNCATED]"
            final_prompt = RAG_PROMPT.format(
                chat_history="",
                context=context,
                question=cleaned_q
            )

        # 5. Generate Response
        print(f"[*] Generating answer (Prompt Length: {len(final_prompt)} chars)...")
        response = LLM.invoke(final_prompt)

        return {
            "id": f"chatcmpl-{int(time.time())}",
            "object": "chat.completion",
            "created": int(time.time()),
            "model": request.model,
            "choices": [
                {
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": response
                    },
                    "finish_reason": "stop"
                }
            ]
        }
    except Exception as e:
        print(f"ERROR in chat_completions: {e}")
        return {
            "choices": [
                {
                    "message": {
                        "role": "assistant",
                        "content": f"Hata olustu: {str(e)}"
                    }
                }
            ]
        }

