            "args": {
              "file_path": "scripts/force_fix_encoding.py",
              "content": "import json\nimport os\n\ndef fix_mojibake(text):\n    if not text:\n        return text\n    try:\n        # The text is currently UTF-8 but contains characters that were double-encoded \n        # or mis-interpreted during a previous write.\n        # This specific pattern (AÄŸustos -> Ağustos) is a classic UTF-8 to Latin-1 mis-read.\n        return text.encode('utf-8').decode('utf-8').encode('latin-1').decode('utf-8')\n    except (UnicodeEncodeError, UnicodeDecodeError):\n        return text\n\ndef forceful_fix(file_path):\n    print(f\"Forcefully fixing encoding in {file_path}...\")\n    temp_path = file_path + \".tmp\"\n    \n    with open(file_path, 'r', encoding='utf-8') as f_in, \\\n         open(temp_path, 'w', encoding='utf-8') as f_out:\n        for line in f_in:\n            data = json.loads(line)\n            \n            # Fields to check\n            for key in [\"text\", \"context\", \"response\"]:\n                if key in data:\n                    data[key] = fix_mojibake(data[key])\n            \n            # Check metadata title\n            if \"metadata\" in data and \"title\" in data[\"metadata\"]:\n                data[\"metadata\"][\"title\"] = fix_mojibake(data[\"metadata\"][\"title\"])\n                \n            f_out.write(json.dumps(data, ensure_ascii=False) + \"\\n\")\n    \n    os.replace(temp_path, file_path)\n    print(f\"Finished processing {file_path}\")\n\nif __name__ == \"__main__\":\n    paths = [\"data/processed/train.jsonl\", \"data/processed/val.jsonl\", \"data/processed/test.jsonl\"]\n    for p in paths:\n        if os.path.exists(p):\n            forceful_fix(p)\n"
