            "id": "write_file__write_file_1780272301922_0",
            "name": "write_file",
            "args": {
              "content": "import json\nimport os\n\n# Mapping for the most common UTF-8 mojibake characters in Turkish\nMOJIBAKE_MAP = {\n    \"ÄŸ\": \"ğ\",\n    \"Ä\": \"Ğ\",\n    \"Ä±\": \"ı\",\n    \"Ä°\": \"İ\",\n    \"Ã¶\": \"ö\",\n    \"Ã–\": \"Ö\",\n    \"Ã¼\": \"ü\",\n    \"Ãœ\": \"Ü\",\n    \"ÅŸ\": \"ş\",\n    \"Å\": \"Ş\",\n    \"Ã§\": \"ç\",\n    \"Ã‡\": \"Ç\",\n    \"â€™\": \"'\",\n    \"â€œ\": \"“\",\n    \"â€\": \"”\",\n}\n\ndef manual_replace(text):\n    if not text:\n        return text\n    for mojibake, correct in MOJIBAKE_MAP.items():\n        text = text.replace(mojibake, correct)\n    return text\n\ndef fix_file(file_path):\n    print(f\"Manually fixing {file_path}...\")\n    temp_path = file_path + \".tmp\"\n    \n    with open(file_path, 'r', encoding='utf-8') as f_in, \\\n         open(temp_path, 'w', encoding='utf-8') as f_out:\n        for line in f_in:\n            data = json.loads(line)\n            \n            # Fix text fields\n            for key in [\"text\", \"context\", \"response\"]:\n                if key in data:\n                    data[key] = manual_replace(data[key])\n            \n            # Fix nested metadata\n            if \"metadata\" in data:\n                if \"title\" in data[\"metadata\"]:\n                    data[\"metadata\"][\"title\"] = manual_replace(data[\"metadata\"][\"title\"])\n                \n            f_out.write(json.dumps(data, ensure_ascii=False) + \"\\n\")\n            \n    os.replace(temp_path, file_path)\n    print(f\"Fixed {file_path}\")\n\nif __name__ == \"__main__\":\n    paths = [\"data/processed/train.jsonl\", \"data/processed/val.jsonl\", \"data/processed/test.jsonl\"]\n    for p in paths:\n        if os.path.exists(p):\n            fix_file(p)\n",
